{
  "hechos": [
    {
      "id": "H1",
      "texto": "Desde las 10 de la noche y hasta las 5 de la mañana regirá un toque de queda en Puerto Celeste.",
      "paginas": ["P1", "P2", "P3", "P4", "P5"]
    },
    {
      "id": "H2",
      "texto": "La medida estará vigente durante 15 días.",
      "paginas": ["P1", "P3"]
    },
    {
      "id": "H3",
      "texto": "El alza en los hurtos a casas durante el último mes motivó la restricción.",
      "paginas": ["P1", "P2", "P3", "P4"]
    },
    {
      "id": "H4",
      "texto": "Quienes incumplan la medida podrán recibir multas de hasta 800.000 pesos.",
      "paginas": ["P1", "P3", "P5"]
    },
    {
      "id": "H5",
      "texto": "El toque de queda regirá por quince días.",
      "paginas": ["P1", "P2", "P4", "P5"]
    },
    {
      "id": "H6",
      "texto": "Un policía que pidió no ser citado aseguró que se planea extender la medida a todo el departamento.",
      "paginas": ["P1", "P2", "P3", "P4"]
    },
    {
      "id": "H7",
      "texto": "En el barrio El Carmen, la junta de acción comunal registró 139 denuncias de robo en el último mes.",
      "paginas": ["P1"]
    },
    {
      "id": "H8",
      "texto": "En el barrio La Pradera, la junta de acción comunal registró 192 denuncias de robo en el último mes.",
      "paginas": ["P2"]
    },
    {
      "id": "H9",
      "texto": "En el barrio El Bosque, la junta de acción comunal registró 373 denuncias de robo en el último mes.",
      "paginas": ["P3"]
    },
    {
      "id": "H10",
      "texto": "En el barrio La Floresta, la junta de acción comunal registró 176 denuncias de robo en el último mes.",
      "paginas": ["P4"]
    }
  ]
}
